import{Z as t,e as i,f as o,a0 as n}from"./chunks/framework.DmpHOl9T.js";const u=JSON.parse('{"title":"Stripe","description":"","frontmatter":{},"headers":[],"relativePath":"integrations/payments/stripe.md","filePath":"integrations/payments/stripe.md","lastUpdated":1782179604000}'),s={name:"integrations/payments/stripe.md"};function r(a,e,l,c,p,d){return i(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="stripe" tabindex="-1">Stripe <a class="header-anchor" href="#stripe" aria-label="Permalink to &quot;Stripe&quot;">​</a></h1><p>Connect Stripe to take payments through the provider configured for your form. You need access to configure the form in Craft and credentials for the destination account. The steps below establish the connection; finish by sending a test submission to verify the result.</p><h3 id="step-1-create-the-integration" tabindex="-1">Step 1. Create the Integration <a class="header-anchor" href="#step-1-create-the-integration" aria-label="Permalink to &quot;Step 1. Create the Integration&quot;">​</a></h3><ol><li>Navigate to <strong>Formie</strong> → <strong>Settings</strong> → <strong>Payments</strong>.</li><li>Click the <strong>New Integration</strong> button.</li><li>Select <strong>Stripe</strong> as the <strong>Integration Provider</strong>.</li></ol><h3 id="step-2-connect-to-the-stripe-api" tabindex="-1">Step 2. Connect to the Stripe API <a class="header-anchor" href="#step-2-connect-to-the-stripe-api" aria-label="Permalink to &quot;Step 2. Connect to the Stripe API&quot;">​</a></h3><ol><li>Go to your <a href="https://dashboard.stripe.com/apikeys" target="_blank">Stripe Developers - API Keys</a> page in your Stripe dashboard.</li><li>On the top-right of your screen, ensure the <strong>Test Mode</strong> lightswitch is in the <strong>off</strong> position if you wish to use Live details, or <strong>on</strong> if you wish to use Test details.</li><li>Copy the <strong>Publishable Key</strong> from Stripe and paste in the <strong>Publishable Key</strong> field in Formie.</li><li>Copy the <strong>Secret Key</strong> from Stripe and paste in the <strong>Secret Key</strong> field in Formie.</li><li>We <strong>strongly recommend</strong> you use <code>.env</code> variables to store these keys.</li></ol><h3 id="step-3-test-connection" tabindex="-1">Step 3. Test Connection <a class="header-anchor" href="#step-3-test-connection" aria-label="Permalink to &quot;Step 3. Test Connection&quot;">​</a></h3><ol><li>Save this integration.</li><li>Click on the <strong>Refresh</strong> button in the right-hand sidebar.</li></ol><h3 id="step-4-configure-webhooks-for-subscriptions" tabindex="-1">Step 4. Configure Webhooks (for Subscriptions) <a class="header-anchor" href="#step-4-configure-webhooks-for-subscriptions" aria-label="Permalink to &quot;Step 4. Configure Webhooks (for Subscriptions)&quot;">​</a></h3><ol><li>In order for subscriptions to work, you must populate some settings for webhooks.</li><li>In Stripe, on the left-hand sidebar menu, click <strong>Developers</strong>.</li><li>On the top sub-menu, click <strong>Webhooks</strong>.</li><li>Click the <strong>Create an event destination</strong> button.</li><li>Copy the <strong>Redirect URI</strong> from the Formie integration settings and paste in the <strong>Endpoint URL</strong> in Stripe.</li><li>Click the <strong>Select Events</strong> button under the &quot;Select events to listen to&quot; heading.</li><li>We recommend emitting all possible events, but the required events are: <ul><li><code>customer.subscription.created</code></li><li><code>customer.subscription.deleted</code></li><li><code>customer.subscription.updated</code></li><li><code>invoice.created</code></li><li><code>invoice.payment_failed</code></li><li><code>invoice.payment_succeeded</code></li><li><code>payment_intent.succeeded</code></li><li><code>payment_intent.payment_failed</code></li><li><code>payment_intent.canceled</code></li><li><code>plan.deleted</code></li><li><code>plan.updated</code></li></ul></li><li>Once created look for the <strong>Signing secret</strong> item and click <strong>Reveal Secret</strong>.</li><li>Copy the <strong>Signing secret</strong> from Stripe and paste in the <strong>Webhook Signing Secret</strong> field in Formie.</li></ol><h3 id="step-5-field-setting" tabindex="-1">Step 5. Field Setting <a class="header-anchor" href="#step-5-field-setting" aria-label="Permalink to &quot;Step 5. Field Setting&quot;">​</a></h3><ol><li>Go to the form you want to enable this integration on.</li><li>Add a <strong>Payment</strong> field to your form.</li><li>Select Stripe for the <strong>Payment Provider</strong>.</li></ol><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Your form <strong>must</strong> use the Ajax (Client-side) submission method when using the Stripe payment integration in your form.</p></div><p>The Stripe payment integration supports both once-off payments and subscription-based payments.</p><h3 id="subscription-payment-limits" tabindex="-1">Subscription Payment Limits <a class="header-anchor" href="#subscription-payment-limits" aria-label="Permalink to &quot;Subscription Payment Limits&quot;">​</a></h3><p>For subscription payments, you can optionally limit how many recurring payments Stripe collects before the subscription is cancelled automatically.</p><ol><li>Edit your <strong>Payment</strong> field and set <strong>Payment Type</strong> to <strong>Subscription</strong>.</li><li>Under <strong>Payment Limit</strong>, choose <strong>Fixed Value</strong> or <strong>Dynamic Value</strong>.</li><li>For a fixed limit, enter the number of payments (for example <code>3</code> for three installments).</li><li>For a dynamic limit, select a field that provides the payment count (for example a <strong>Number</strong> field).</li></ol><p>When a limit is set, Formie creates the subscription through a Stripe subscription schedule. Stripe cancels the subscription after the configured number of successful billing cycles. Leave <strong>Payment Limit</strong> set to <strong>No limit</strong> for ongoing subscriptions.</p><h3 id="subscription-setup-fees" tabindex="-1">Subscription Setup Fees <a class="header-anchor" href="#subscription-setup-fees" aria-label="Permalink to &quot;Subscription Setup Fees&quot;">​</a></h3><p>For subscription payments, you can optionally charge a one-time setup fee on the first invoice, in addition to the recurring subscription amount.</p><ol><li>Edit your <strong>Payment</strong> field and set <strong>Payment Type</strong> to <strong>Subscription</strong>.</li><li>Under <strong>Setup Fee</strong>, choose <strong>Fixed Value</strong> or <strong>Dynamic Value</strong>.</li><li>For a fixed fee, enter the amount (for example <code>50</code>).</li><li>For a dynamic fee, select a field that provides the fee amount.</li><li>Optionally set <strong>Setup Fee Description</strong> for the Stripe invoice line item.</li></ol><p>The setup fee is added to the first subscription invoice through Stripe <code>add_invoice_items</code>. It works with both standard subscriptions and subscriptions that use a payment limit schedule.</p><p>You can modify subscription payloads through the <code>modifySubscriptionPayload</code> and <code>modifySubscriptionSchedulePayload</code> events.</p><h2 id="verify-a-submission" tabindex="-1">Verify a Submission <a class="header-anchor" href="#verify-a-submission" aria-label="Permalink to &quot;Verify a Submission&quot;">​</a></h2><p>Save the form, open it on your site and submit recognisable test values. Complete a test payment and inspect both the saved submission and the provider’s transaction record. Confirm the amount, currency and final payment state before enabling live payments.</p><p>If nothing arrives, check whether integration conditions matched, whether the submission was complete and non-spam, and whether Craft’s queue has processed the job. A successful connection check verifies credentials; it does not prove that field mapping and delivery work. See <a href="/integrations/connect-and-test-an-integration">Connect and Test an Integration</a> for a complete mapping and verification workflow.</p>',26)])])}const g=t(s,[["render",r]]);export{u as __pageData,g as default};
